// Mini Heroes 1.5 painted UI layer: Broz icon atlas (64px), home screen, faction grid, talent tree + policy cards with
// tap-for-detail, mage guild / spellbook icons, win/lose art, event popups, battle props (obstacles, siege, spell fx).
// Pure presentation: game rules stay in game.js; everything here decorates or replaces render paths and falls back to the
// old pixel art while atlases load. Atlas metadata (UIA) comes from ui-art-data.js (generated by build_ui.py).
(() => {
  const A = 'art/', IC = UIA.icons, BP = UIA.battle, EV = UIA.events;
  const SPELL_ICON = {arrow: 'fireball', cure: 'heal', haste: 'haste', lightning: 'lightning', slow: 'curse'};
  const SPELL_FX = {arrow: 'fx_fireball', cure: 'fx_heal', haste: 'fx_haste', lightning: 'fx_lightning', slow: 'fx_curse'};
  const ART_ICON = {sword: 'art_sword', shield: 'art_shieldA', orb: 'art_orb', tome: 'art_book', boots: 'art_boots'};
  const POL_ICON = {tax: 'tax', lumber: 'wood', trade: 'trade', warchest: 'gold', conscript: 'militia', muster: 'leadership', fortify: 'defense', drill: 'attack',
    manafont: 'manaregen', tithe: 'research', carto: 'logistics', ley: 'air', crusade: 'tal_castle_2', divine: 'tal_castle_1', raisedead: 'tal_necro_0', dread: 'tal_necro_5',
    sacredwood: 'tal_sylvan_5', huntlaw: 'archery', hellforge: 'tal_inferno_2', pact: 'tal_inferno_3', warband: 'tal_stronghold_1', plunder: 'tal_stronghold_2',
    guildhall: 'tal_dwarf_4', bulwark: 'tal_dwarf_2', growth: 'growth', construction: 'construction'};
  const BLD = {fort: 'defense', citadel: 'tal_castle_0', hall: 'gold', capitol: 'art_crown', market: 'trade', guild1: 'wisdom', guild2: 'manaregen', pit: 'fire'};
  const icoKey = k => IC.cells[k] ? k : POL_ICON[k] || SPELL_ICON[k] || ART_ICON[k] || null;
  // CSS sprite: works before the image decodes, scales to any px
  const ico = (k, px = 32, cls = '') => { const key = icoKey(k), c = key && IC.cells[key]; if (!c) return ''; const s = px / IC.size;
    return `<span class="ico ${cls}" style="width:${px}px;height:${px}px;background-position:${-c[0] * s}px ${-c[1] * s}px;background-size:${1024 * s}px auto"></span>`; };
  window.ico = ico;
  // ---- images: icon atlas cut to data URLs (resImg), battle props cut to canvases
  const img = src => { const i = new Image(); i.src = A + src; return i; };
  const icons = img(IC.img), props = img(BP.img), cut = {}, pc = {};
  const cell = (im, M, k) => { const c = M.cells[k]; if (!c || !im.complete || !im.naturalWidth) return null; const cv = document.createElement('canvas'); cv.width = cv.height = M.size; cv.getContext('2d').drawImage(im, c[0], c[1], M.size, M.size, 0, 0, M.size, M.size); return cv; };
  const oldRes = resImg;
  resImg = k => { if (cut[k]) return cut[k]; const cv = cell(icons, IC, k === 'crystal' ? 'crystal' : k); if (!cv) return oldRes(k); return (cut[k] = cv.toDataURL()); };
  policyIcons = o => (KG(o) ? KG(o).slots : []).map(k => `<span class="pi ico-pi" title="${POLICIES[k].name}: ${POLICIES[k].desc}">${ico(k, 22)}</span>`).join('');
  icons.onload = () => { try { hudSig = ''; } catch (e) {} };
  const prop = k => pc[k] || (pc[k] = cell(props, BP, k));
  window.PROPS = {
    ok: () => props.complete && props.naturalWidth > 0,
    // draw prop k centred on hex (x,y), w = width in field px; returns false when the atlas is not ready (caller falls back)
    draw(g, k, x, y, w, a = 1) { const c = prop(k); if (!c) return false; const [cx, cy] = cellC(x, y); const pa = g.globalAlpha; g.globalAlpha = pa * a; g.drawImage(c, cx - w / 2, cy + RH * 0.45 - w, w, w); g.globalAlpha = pa; return true; },
    obst: key => ['boulder', 'rocks', 'stump', 'bush', 'crystal', 'bones', 'lava', 'boulder'][[...key].reduce((s, ch) => s * 31 + ch.charCodeAt(0) & 1023, 7) % 8],
    wall: (kind, st) => kind === 'gate' ? (st === 2 ? 'gate_broken' : 'gate') : ['wall', 'wall_dmg', 'wall_rubble'][st]
  };
  // ---- painted spell effects (fallback: the old pixel effect)
  const oldFx = drawSpellFx;
  drawSpellFx = function (g, e) {
    const k = (B.clock - e.at) / 0.6, c = prop(SPELL_FX[e.k]); if (!c) return oldFx(g, e); if (k < 0 || k > 1) return;
    const [x, y] = cellC(e.tx, e.ty);
    if (e.k === 'arrow' && k < 0.45) { const m = prop('fx_meteor'), sx = e.side === 'L' ? 0 : BLW, q = k / 0.45; if (m) g.drawImage(m, sx + (x - sx) * q - 12, BOY + (y - BOY) * q - 12, 24, 24); return; }
    const t = e.k === 'arrow' ? (k - 0.45) / 0.55 : k, w = CW * (1.2 + 0.8 * Math.sin(Math.min(1, t * 1.4) * Math.PI / 2)), pa = g.globalAlpha;
    g.globalAlpha = pa * Math.min(1, (1 - t) * 3); g.drawImage(c, x - w / 2, y - w / 2 - (e.k === 'lightning' ? w * 0.25 : 0), w, w); g.globalAlpha = pa;
  };
  // ---- soft fog edges: 1 px per tile, scaled up with smoothing (a cheap gradient; no per-pixel loops)
  drawFog = function (c) {
    c.width = WW; c.height = WH; const g = c.getContext('2d'), s = document.createElement('canvas'); s.width = MW + 2; s.height = MH + 2; const sg = s.getContext('2d');
    sg.fillStyle = '#05050c'; sg.fillRect(0, 0, MW + 2, MH + 2); for (let y = 0; y < MH; y++) for (let x = 0; x < MW; x++) if (G.fog[y][x]) sg.clearRect(x + 1, y + 1, 1, 1);
    const m = document.createElement('canvas'); m.width = (MW + 2) * 4; m.height = (MH + 2) * 4; const mg = m.getContext('2d'); mg.imageSmoothingEnabled = true; mg.drawImage(s, 0, 0, m.width, m.height);
    g.imageSmoothingEnabled = true; g.drawImage(m, -TS, -TS, (MW + 2) * TS, (MH + 2) * TS);
    for (let y = 0; y < MH; y++) for (let x = 0; x < MW; x++) if (!G.fog[y][x]) { let n = 0; for (const [dx, dy] of DIRS8) if (inMap(x + dx, y + dy) && G.fog[y + dy][x + dx]) n++; if (!n) { g.fillStyle = '#05050c'; g.fillRect(x * TS, y * TS, TS, TS); } }
  };
  // ---- shrine / spell learning popup + artifact popup art
  CELE_COL.spell = ['#b07cff', '#e2ccff'];
  const oldNext = nextCele;
  nextCele = function () {
    const c = UI.celeQ && UI.celeQ[0]; oldNext();
    if (!c) return; const box = document.querySelector('#cele .cbox'); if (!box) return;
    const ev = c.kind === 'spell' ? 'shrine' : null, ak = c.kind === 'art' && Object.keys(ARTIFACTS).find(k => c.text.startsWith(ARTIFACTS[k].name.toUpperCase())), art = ak && ART_ICON[ak];
    if (ev) box.insertAdjacentHTML('afterbegin', evArt(ev, 150)); else if (art) box.insertAdjacentHTML('afterbegin', ico(art, 72)); else if (c.kind === 'xp' && c.ic) box.insertAdjacentHTML('afterbegin', ico(c.ic, 72, 'gold'));
  };
  const evArt = (k, px) => { const c = EV.cells[k], s = px / EV.size; return `<span class="evart" style="width:${px}px;height:${px}px;background-position:${-c[0] * s}px ${-c[1] * s}px;background-size:${768 * s}px auto"></span>`; };
  window.evArt = evArt;
  // ---- HOME screen
  const home = document.createElement('div'); home.id = 'home';
  const HB = [['CONTINUE', 'h_cont', 0], ['NEW GAME', 'new', 1], ['CAMPAIGN', 'campaign', 2], ['DUEL', 'h_duel', 3], ['SETTINGS', 'h_set', 4]];
  const homeHtml = () => { const can = !!(localStorage.getItem(SAVE_KEY + '-auto') || localStorage.getItem(SAVE_KEY));
    return `<div class="hbg"></div><nav>${HB.map(([l, a, i]) => `<button class="hbtn${a === 'campaign' ? ' hot' : ''}" data-a="${a}" ${a === 'h_cont' && !can ? 'disabled' : ''}><img src="${A}home-i${i}.webp" alt="">${l}</button>`).join('')}</nav><small class="hver">v${'1.5.0'}</small>`; };
  window.showHome = () => { home.innerHTML = homeHtml(); home.style.display = 'flex'; UI.panel = null; $('panel').classList.remove('show'); UI.mode = G ? UI.mode : 'title'; };
  const hideHome = () => { home.style.display = 'none'; };
  document.body.appendChild(home);
  home.addEventListener('click', e => { const b = e.target.closest('[data-a]'); if (!b || b.disabled) return; e.stopPropagation(); hideHome(); SFX.pick && SFX.pick(); ACTIONS[b.dataset.a](b.dataset.v); });
  ACTIONS.h_cont = () => { if (localStorage.getItem(SAVE_KEY + '-auto')) ACTIONS.loadauto(); else ACTIONS.load(); if (!G) showHome(); };
  ACTIONS.h_duel = () => { UI.setup = Object.assign(UI.setup || {}, {size: Object.keys(MAP_SIZES)[0], diff: 'normal', seed: Math.floor(Math.random() * 1e6), pf: (UI.setup || {}).pf || 'castle', af: 'random'}); openSetup(); };
  ACTIONS.h_set = () => openMenu();
  ACTIONS.home = () => { closePanel(); showHome(); };
  // closing a panel with no game running returns to the home screen
  const oldClose = closePanel;
  closePanel = function () { oldClose(); if (!G && !UI.panel) showHome(); };
  // ---- decorators: run after every panel / book render (MutationObserver), idempotent via .dec markers
  const PB = $('pbox');
  function decorate() {
    if (!PB) return; mo.disconnect();
    try {
      // faction select: data-driven card grid from whatever setpf / setaf buttons the setup panel renders
      for (const a of ['setpf', 'setaf']) { const bs = PB.querySelectorAll(`[data-a=${a}]`); if (!bs.length || bs[0].classList.contains('fcard')) continue;
        bs[0].parentElement.classList.add('fgrid');
        bs.forEach(b => { const k = b.dataset.v, F = FACTIONS[k]; b.classList.add('fcard'); b.style.setProperty('--fc', F ? F.col : '#888');
          b.innerHTML = (F ? unitPic(F.units[F.units.length - 1]) : '<b class="rq">?</b>') + `<span>${F ? F.name : 'Random'}</span>`; }); }
      // spellbook + mage guild + hero spells: icons on cast buttons and spell rows
      PB.querySelectorAll('[data-a=cast]:not(.dec)').forEach(b => { b.classList.add('dec'); if (b.dataset.v) { const row = b.closest('.it'); (row || b).insertAdjacentHTML('afterbegin', ico(b.dataset.v, 36)); } });
      PB.querySelectorAll('h3').forEach(h => { if (h.textContent.trim() === 'MAGE GUILD' && !h.classList.contains('dec')) { h.classList.add('dec'); h.insertAdjacentHTML('afterbegin', ico('wisdom', 28)); const p = h.nextElementSibling;
        if (p) p.insertAdjacentHTML('afterbegin', `<span class="srow">${Object.keys(SPELLS).filter(k => p.textContent.includes(SPELLS[k].name)).map(k => ico(k, 40)).join('')}</span>`); } });
      if (UI.panel && UI.panel.kingdom) policyCards();
      if (UI.panel && UI.panel.tech) talentTree();
      if (UI.panel && UI.panel.chestHero && !PB.querySelector('.evart')) PB.insertAdjacentHTML('afterbegin', `<div class="evhead">${evArt('chest', 180)}</div>`), PB.classList.add('evpop');
      if (G && G.over && !PB.querySelector('.endart')) endScreen();
    } finally { mo.observe(PB, {childList: true}); }
  }
  const mo = new MutationObserver(decorate);
  if (PB) mo.observe(PB, {childList: true});
  const bookEl = $('book');
  if (bookEl) new MutationObserver(() => bookEl.querySelectorAll('[data-a=cast]:not(.dec)').forEach(b => { b.classList.add('dec'); if (b.dataset.v) b.insertAdjacentHTML('afterbegin', ico(b.dataset.v, 28)); })).observe(bookEl, {childList: true, subtree: true});
  // ---- detail card (talents / policies)
  function detail(o) {
    PB.querySelectorAll('.dcard').forEach(e => e.remove());
    PB.insertAdjacentHTML('beforeend', `<div class="dcard"><div class="dbox">${ico(o.icon, 96, o.state)}<h3>${o.name}</h3><p>${o.desc}</p>${o.cost ? `<p class="dcost">${o.cost}</p>` : ''}${o.why ? `<p class="no">${o.why}</p>` : ''}
      <div class="bar">${o.act ? `<button class="btn g" data-a="${o.act}" data-v="${o.v}" ${o.can ? '' : 'disabled'}>${o.label}</button>` : ''}<button class="btn alt" data-a="dclose">CLOSE</button></div></div></div>`);
  }
  ACTIONS.dclose = () => { PB.querySelectorAll('.dcard').forEach(e => e.remove()); UI.det = null; };
  ACTIONS.det = v => { const [kind, k] = v.split(':'); UI.det = v; (kind === 'p' ? polDetail : talDetail)(k); };
  // ---- KINGDOM POLICY: symbol cards (active glow, locked dim), tap = detail with ACTIVATE
  function policyCards() {
    const old = PB.querySelector('.cols3'); if (!old || PB.querySelector('.pgrid')) return;
    const o = 'player', K = KG(o);
    const keys = Object.keys(POLICIES).filter(k => !POLICIES[k].faction || POLICIES[k].faction === K.faction);
    old.outerHTML = `<div class="pgrid">${keys.map(k => { const p = POLICIES[k], on = K.slots.includes(k), why = policyOK(o, k);
      return `<button class="pcard ${on ? 'on' : why ? 'lock' : ''}" data-a="det" data-v="p:${k}" style="--pc:${POLICY_CATS[p.cat].col}">${ico(k, 52)}<span>${p.name}</span>${on ? '<b>ACTIVE</b>' : ''}</button>`; }).join('')}</div>`;
    if (UI.det && UI.det[0] === 'p') polDetail(UI.det.slice(2));
  }
  function polDetail(k) {
    const o = 'player', K = KG(o), p = POLICIES[k], on = K.slots.includes(k), why = policyOK(o, k), free = K.slots.length < slotCount(o) || K.slots.some(s => !s);
    detail({icon: k, state: on ? 'gold' : '', name: p.name, desc: p.desc, cost: free ? 'Empty slot: free' : 'Swap cost ' + swapCost(o) + ' gold (Day 1 of a week)' + (UI.kslot != null ? ' · replaces slot ' + (UI.kslot + 1) : ' · tap a slot first'),
      why: on ? 'Already active' : why, act: 'kact', v: k, can: !on && !why && (free || UI.kslot != null), label: 'ACTIVATE'});
  }
  ACTIONS.kact = k => { const K = KG('player'); if (UI.kslot == null) { const i = Array.from({length: slotCount('player')}, (_, i) => i).find(i => !K.slots[i]); if (i == null) return; UI.kslot = i; } UI.det = null; ACTIONS.kpol(k); };
  // ---- FACTION TALENT TREE (tech): 6 levels x 3 icon nodes; learned gold, available glowing, locked padlock; tap = detail with LEARN
  function talentTree() {
    const rows = PB.querySelectorAll('.tl'); if (!rows.length || PB.querySelector('.ttree')) return;
    const o = 'player', f = facOf(o);
    const html = `<div class="ttree">${TECH[f].map((lv, i) => `<div class="tlv"><b>LV${i + 1}<small>${TECH_COST[i]}pt</small></b>${lv.map((t, j) => { const st = techState(o, i, t.k), cls = st === 'have' ? 'gold' : st === 'open' ? 'glow' : st === 'poor' ? 'dim' : 'lock';
      return `<button class="tnode ${cls}" data-a="det" data-v="t:${t.k}" style="--h:${(j - 1) * 38}deg">${ico('tal_' + f + '_' + i, 54)}${cls === 'lock' || cls === 'dim' && i > 0 && !RS(o).picks[i - 1] ? '<i class="pad">🔒</i>' : ''}<span>${t.name}</span></button>`; }).join('')}</div>`).join('')}</div>`;
    rows[0].insertAdjacentHTML('beforebegin', html); rows.forEach(r => r.remove());
    if (UI.det && UI.det[0] === 't') talDetail(UI.det.slice(2));
  }
  function talDetail(k) {
    const o = 'player', f = facOf(o), i = TECH[f].findIndex(lv => lv.some(t => t.k === k)), t = TECH[f][i].find(t => t.k === k), st = techState(o, i, k);
    detail({icon: 'tal_' + f + '_' + i, state: st === 'have' ? 'gold' : st === 'open' ? 'glow' : 'lock', name: t.name, desc: t.desc, cost: TECH_COST[i] + ' research point' + (TECH_COST[i] > 1 ? 's' : '') + ' · you have ' + RS(o).pts,
      why: st === 'have' ? 'Learned' : st === 'other' ? 'Another talent was chosen on this level' : st === 'locked' ? 'Learn a level ' + i + ' talent first' : st === 'poor' ? 'Not enough research points' : '', act: 'tlearn', v: k, can: st === 'open', label: 'LEARN'});
  }
  ACTIONS.tlearn = k => { UI.det = null; ACTIONS.ptech(k); };
  // ---- WIN / LOSE
  function endScreen() {
    const win = G.over === 'win', h2 = PB.querySelector('h2'); if (!h2) return;
    h2.insertAdjacentHTML('beforebegin', `<div class="endart ${win ? 'win' : 'lose'}"><img src="${A}${win ? 'win' : 'lose'}.webp" alt="${win ? 'Victory' : 'Defeat'}"></div>`);
    const st = PB.querySelector('.bar'); if (st && !st.querySelector('[data-a=home]')) st.insertAdjacentHTML('beforeend', '<button class="btn alt" data-a="home">MAIN MENU</button>');
    PB.classList.add('endp');
  }
  // boot: replace the start-up menu with the home screen
  if (!G) showHome();
})();
